# اجبار به استفاده‌ی فقط IPv4 تو همه‌ی درخواست‌های requests. دلیلش: خطایی
# که داشتیم (ConnectTimeoutError موقع اتصال به botapi.rubika.ir) دقیقاً
# علامت رایج «مسیر IPv6 سرور مسدود/خرابه ولی IPv4 سالمه» است — وقتی یه
# دامنه هم آدرس IPv4 هم IPv6 داشته باشه، سیستم گاهی اول IPv6 رو امتحان
# می‌کنه و رو همون گیر می‌کنه، بدون اینکه اصلاً IPv4 رو تست کنه. این
# اصلاح، DNS resolution کتابخونه‌ی شبکه رو مجبور می‌کنه فقط دنبال آدرس
# IPv4 (AF_INET) بگرده، برای همه‌ی درخواست‌های requests.post/get تو کل
# برنامه — بدون نیاز به تغییر تک‌تک جاهایی که ازش استفاده شده.
_urllib3_cn.allowed_gai_family = lambda: socket.AF_INET

TOKEN = os.environ.get("BOT_TOKEN", "TOKEN_KHODETO_INJA_BEZAR")
BASE_URL = f"https://botapi.rubika.ir/v3/{TOKEN}"

# اگه فعال باشه، به‌جای پولینگ (هر ۱ ثانیه پرسیدن "پیام جدید داری؟")،
# روبیکا خودش فوری پیام رو به سرورمون پوش می‌کنه (سریع‌تر و بدون تأخیر پولینگ).
# چون این بخش از API روبیکا قبلاً امتحان نشده، اگه کار نکرد فقط این متغیر
# محیطی رو تو Render بذار روی false تا خودکار برگردیم به همون پولینگ قدیمی.
USE_WEBHOOK = os.environ.get("USE_WEBHOOK", "true").lower() == "true"
