@app.route(WEBHOOK_PATH, methods=["POST"])
def webhook():
    try:
        data = request.get_json(force=True, silent=True) or {}
        print("پیام وبهوک دریافت شد:", data)
        # روبیکا احتمالاً یا خودِ آپدیت رو مستقیم می‌فرسته، یا زیر یه کلید
        # مثل "update" بسته‌بندیش می‌کنه؛ هر دو حالت رو پوشش می‌دیم.
        update = data.get("update") if isinstance(data, dict) and "update" in data else data
        process_update(update)
    except Exception:
        print("خطا در پردازش وبهوک:")
        traceback.print_exc()
    return jsonify({"status": "ok"})


def register_webhook():
    service_url = os.environ.get("RENDER_EXTERNAL_URL") or os.environ.get("WEBHOOK_BASE_URL")
    if not service_url:
        print("⚠️ آدرس سرویس برای ثبت وبهوک پیدا نشد؛ اگه رو Render نیستی، متغیر WEBHOOK_BASE_URL رو دستی ست کن.")
        return
    webhook_url = service_url.rstrip("/") + WEBHOOK_PATH
    try:
        # روبیکا متدی به اسم setWebHook نداره؛ متد درست updateBotEndpoints هست
        # و یه فیلد type هم لازم داره تا مشخص کنه این آدرس برای چه نوع
        # رویدادیه. ReceiveUpdate یعنی پیام‌های معمولی (متن/ریپلای/...).
        resp = requests.post(
            f"{BASE_URL}/updateBotEndpoints",
            json={"url": webhook_url, "type": "ReceiveUpdate"},
            timeout=15,
        )
        print("نتیجه‌ی ثبت وبهوک:", resp.status_code, resp.text)
    except Exception as e:
        print("خطا در ثبت وبهوک:", e)


def get_updates(offset_id=None):
    payload = {"limit": 10}
    if offset_id:
        payload["offset_id"] = offset_id
    try:
        resp = requests.post(f"{BASE_URL}/getUpdates", json=payload, timeout=15)
        if resp.status_code != 200:
            print("خطای HTTP در دریافت آپدیت:", resp.status_code, resp.text)
            return None
        return resp.json()
    except Exception as e:
        print("خطا در دریافت آپدیت:", e)
        return None


def _utf16_length(s):
    """
    روبیکا طول متن برای metadata رو با واحد UTF-16 می‌شمره، نه با len() پایتون.
    اموجی‌های خارج از BMP (اکثر اموجی‌هایی که استفاده می‌کنیم) هرکدوم ۲ واحد
    UTF-16 حساب می‌شن ولی len() پایتون فقط ۱ می‌شمردشون. همین اختلاف باعث
    می‌شد بازه‌ی بولد زودتر از پایان واقعی متن تموم بشه و آخر جمله بولد نباشه.
    """
    return len(s.encode("utf-16-le")) // 2


def send_message(chat_id, text, reply_to_message_id=None):
    # همون روشی که قبلاً واقعاً کار می‌کرد: نیازی به ** نیست، کل متن پیام
    # یه بازه‌ی Bold از ابتدا تا انتها می‌گیره (از_index=0 تا طول کامل متن
    # بر حسب UTF-16). اگه به هر دلیلی روبیکا رد کرد، کل بدنه‌ی پاسخ رو
    # لاگ می‌کنیم (نه فقط کد وضعیت) و بدون بولد دوباره می‌فرستیم تا
    # پیام گم نشه.
    #
    # مقدار برگشتی: True اگه پیام واقعاً تحویل داده شد، False اگه هر سه
    # تلاش (بولد + ساده + تلاش دومِ ساده) شکست خوردن. صداکننده‌هایی که
    # قبل از این تابع یه تغییر برگشت‌ناپذیر تو دیتابیس انجام دادن (مثلاً
    # کم کردن شرط و شروع یه بازی) باید این مقدار رو چک کنن، وگرنه بازیکن
    # پولش کم می‌شه ولی هیچ پیامی نمی‌بینه و بازی به‌صورت نامرئی می‌مونه
    # تا خودکار تایم‌اوت بشه (باگی که باعث نوشتن این توضیح شد).
    metadata = None
    if text:
        metadata = {
            "meta_data_parts": [
                {"from_index": 0, "length": _utf16_length(text), "type": "Bold"}
            ]
        }

    payload = {"chat_id": chat_id, "text": text}
    if metadata:
        payload["metadata"] = metadata
    if reply_to_message_id:
        payload["reply_to_message_id"] = reply_to_message_id

    try:
        resp = requests.post(f"{BASE_URL}/sendMessage", json=payload, timeout=15)
        if resp.status_code != 200:
            print("خطای HTTP در ارسال پیام (تلاش با متادیتای بولد):", resp.status_code, resp.text)
            raise RuntimeError("send with bold metadata failed, will retry plain")
        try:
            data = resp.json()
        except ValueError:
            data = None
        if isinstance(data, dict) and data.get("status") not in (None, "OK", "ok", "done", "Done"):
            print("خطای منطقی سرور در ارسال پیام (تلاش با متادیتای بولد):", data)
            raise RuntimeError("send with bold metadata returned error status, will retry plain")
        return True
    except Exception as e:
        print("پیام با متادیتای بولد ارسال نشد، تلاش دوباره بدون فرمت:", e)

    fallback_payload = {"chat_id": chat_id, "text": text}
    if reply_to_message_id:
        fallback_payload["reply_to_message_id"] = reply_to_message_id

    # قبلاً اگه همینجا هم شکست می‌خورد، تابع بی‌سروصدا تموم می‌شد و
    # صداکننده اصلاً نمی‌فهمید پیام نرسیده. حالا یه تلاش دوم کوتاه (با
    # کمی مکث) هم اضافه شده، چون خیلی از شکست‌ها موقتی/شبکه‌ای هستن.
    for attempt in (1, 2):
        try:
            resp = requests.post(f"{BASE_URL}/sendMessage", json=fallback_payload, timeout=15)
            if resp.status_code == 200:
                # باگی که قبلاً اینجا بود: فقط کد HTTP چک می‌شد، نه خودِ
                # بدنه‌ی جواب. روبیکا می‌تونه ۲۰۰ برگردونه ولی تو بدنه
                # وضعیت خطا بده (مثلاً وقتی کاربر هیچ‌وقت پیوی بات رو
                # نزده) — که باعث می‌شد send_message موفقیت گزارش بده
                # درحالی‌که پیام اصلاً نرسیده بود.
                try:
                    data = resp.json()
                except ValueError:
                    data = None
                if isinstance(data, dict) and data.get("status") not in (None, "OK", "ok", "done", "Done"):
                    print(f"خطای منطقی سرور در ارسال پیام (تلاش ساده #{attempt}):", data)
                else:
                    return True
            else:
                print(f"خطای HTTP در ارسال پیام (تلاش ساده #{attempt}):", resp.status_code, resp.text)
        except Exception as e:
            print(f"خطا در ارسال پیام (تلاش ساده #{attempt}):", e)
        if attempt == 1:
            time.sleep(1.5)

    return False


def send_message_with_mentions(chat_id, text, mentions, reply_to_message_id=None):
    """
    مثل send_message (کل متن Bold می‌شه)، ولی هر اسمی که تو mentions
    داده بشه، اضافه‌بر Bold یه بازه‌ی MentionText هم می‌گیره و با تپ روش
    پروفایل داخلی اون کاربر باز می‌شه — دقیقاً کاری که بات‌هایی مثل
    Gardi/PawKing انجام می‌دن.

    mentions: لیستی از (name, user_id) — مثلاً برای پیام‌های دو نفره
    (انتقال کوین، دوئل‌ها) هر دو اسم با هم لینک می‌شن. برای هر جفت،
    اولین جایی که name تو متن پیدا بشه (بعد از آخرین منشنِ قبلی، که از
    تداخل و منشن‌شدنِ اشتباهیِ یه رشته‌ی تکراری جلوگیری می‌کنه) استفاده
    می‌شه؛ اگه یه اسم پیدا نشه یا user_id نداشته باشه، فقط همون یکی رد
    می‌شه، بقیه‌ی منشن‌ها و بولدِ کلی پیام دست‌نخورده می‌مونن.

    طبق مستندات رسمی روبیکا (rubika.ir/botapi/methods): type="MentionText"
    + فیلد "mention_text_user_id".
    """
    parts = []
    if text:
        parts.append({"from_index": 0, "length": _utf16_length(text), "type": "Bold"})

    search_from = 0
    for name, user_id in (mentions or []):
        if not name or not user_id or not text:
            continue
        idx = text.find(name, search_from)
        if idx == -1:
            idx = text.find(name)  # شاید ترتیب متن با ترتیب mentions فرق داشته باشه
        if idx == -1:
            continue
        from_index = _utf16_length(text[:idx])
        length = _utf16_length(name)
        parts.append({
            "from_index": from_index,
            "length": length,
            "type": "MentionText",
            "mention_text_user_id": str(user_id),
        })
        search_from = idx + len(name)

    if len(parts) <= 1:
        # هیچ منشنی ساخته نشد — مثل قبل فقط بولد ساده می‌فرستیم که پیام
        # گم نشه (send_message خودش این کارو با فallback انجام می‌ده).
        return send_message(chat_id, text, reply_to_message_id=reply_to_message_id)

    payload = {"chat_id": chat_id, "text": text, "metadata": {"meta_data_parts": parts}}
    if reply_to_message_id:
        payload["reply_to_message_id"] = reply_to_message_id

    try:
        resp = requests.post(f"{BASE_URL}/sendMessage", json=payload, timeout=15)
        if resp.status_code != 200:
            print("خطای HTTP در ارسال پیام با منشن:", resp.status_code, resp.text)
            raise RuntimeError("send with MentionText failed, will retry plain bold")
        try:
            data = resp.json()
        except ValueError:
            data = None
        if isinstance(data, dict) and data.get("status") not in (None, "OK", "ok", "done", "Done"):
            print("خطای منطقی سرور در ارسال پیام با منشن:", data)
            raise RuntimeError("send with MentionText returned error status, will retry plain bold")
        return True
    except Exception as e:
        print("پیام با منشن ارسال نشد، تلاش دوباره با بولد ساده:", e)

    # همون فallback دو-مرحله‌ای send_message (بولد ساده، بعد کاملاً ساده)
    return send_message(chat_id, text, reply_to_message_id=reply_to_message_id)


def send_message_with_mention(chat_id, text, mention_name, mention_user_id, reply_to_message_id=None):
    """نسخه‌ی تک‌منشنیِ send_message_with_mentions، برای سازگاری با جاهایی که فقط یه اسم دارن."""
    return send_message_with_mentions(
        chat_id, text, [(mention_name, mention_user_id)], reply_to_message_id=reply_to_message_id
    )


def send_message_get_id(chat_id, text):
    """
    مثل send_message ولی سعی می‌کنه message_id پیامی که فرستاده رو هم
    برگردونه (برای قابلیت «پاک کردن تبلیغ» بعداً). چون تا حالا این
    قسمت از API رو امتحان نکرده بودیم، مسیرهای مختلف پاسخ رو چک می‌کنه؛
    اگه هیچ‌کدوم نبود، پیام بازم فرستاده می‌شه ولی message_id برابر
    None برمی‌گرده (یعنی اون پیام بعداً قابل حذف خودکار نیست).
    """
    metadata = None
    if text:
        metadata = {
            "meta_data_parts": [
                {"from_index": 0, "length": _utf16_length(text), "type": "Bold"}
            ]
        }

    payload = {"chat_id": chat_id, "text": text}
    if metadata:
        payload["metadata"] = metadata

    try:
        resp = requests.post(f"{BASE_URL}/sendMessage", json=payload, timeout=6)
        if resp.status_code != 200:
            print("خطای HTTP در ارسال پیام تبلیغاتی:", resp.status_code, resp.text)
            return None
        try:
            data = resp.json()
        except ValueError:
            return None
        candidates = []
        if isinstance(data, dict):
            candidates.append(data.get("message_id"))
            inner = data.get("data")
            if isinstance(inner, dict):
                candidates.append(inner.get("message_id"))
                new_msg = inner.get("new_message")
                if isinstance(new_msg, dict):
                    candidates.append(new_msg.get("message_id"))
        for candidate in candidates:
            if candidate:
                return str(candidate)
        return None
    except Exception as e:
        print("خطا در ارسال پیام تبلیغاتی:", e)
        return None


def delete_message(chat_id, message_id):
    try:
        resp = requests.post(
            f"{BASE_URL}/deleteMessage",
            json={"chat_id": chat_id, "message_id": message_id},
            timeout=15,
        )
        if resp.status_code != 200:
            print("خطای HTTP در حذف پیام:", resp.status_code, resp.text)
            return False
        return True
    except Exception as e:
        print("خطا در حذف پیام:", e)
        return False


